<script setup>
import {reactive,watch,ref} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {initialInvitePolicyState,createInvitePolicyFlow} from '../../services/invite-policies.js'
import {imageRequestKey} from '../../services/private-images.js'
import {couponUtcTime,couponLocalTime} from '../../services/coupons.js'
const state=reactive(initialInvitePolicyState()),editing=ref(0),form=reactive({scope:'OWNER',source_note:'',fromDate:'',fromTime:'',toDate:'',toTime:'',inviter:null,invitee:null,revision:0})
const allowed=()=>operatorSession.canInvite,flow=createInvitePolicyFlow({state,token:operatorToken,allowed,newKey:imageRequestKey,onWritten:clearForm,confirm:(kind)=>new Promise(resolve=>uni.showModal({title:'确认邀请规则',content:kind==='status'?'发布冻结规则；停用阻止新政策使用。配置不发券、不占库存。':'保存明确来源、时间与已发布券版本；不会立即发放奖励。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}))})
function clearForm(){editing.value=0;Object.assign(form,{scope:'OWNER',source_note:'',fromDate:'',fromTime:'',toDate:'',toTime:'',inviter:null,invitee:null,revision:0})}
watch(()=>state.kind,k=>{if(['unauthorized','forbidden'].includes(k))clearForm()})
let visible=false
watch(()=>[operatorSession.accessToken,operatorSession.canInvite],()=>{flow.reset();clearForm();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;flow.reset();clearForm()});onUnload(()=>{visible=false;flow.reset();clearForm()})
function select(side,e){form[side]=state.offers[Number(e.detail.value)]||null}
function edit(r){editing.value=r.id;form.scope=r.scope;form.source_note=r.source_note;form.revision=r.revision;const a=couponLocalTime(r.valid_from).split(' '),b=couponLocalTime(r.valid_to).split(' ');[form.fromDate,form.fromTime]=a;[form.toDate,form.toTime]=b;form.inviter=r.inviter_coupon_id?{coupon_id:r.inviter_coupon_id,publication_revision:r.inviter_publication_revision}:null;form.invitee={coupon_id:r.invitee_coupon_id,publication_revision:r.invitee_publication_revision}}
function save(){const from=couponUtcTime(form.fromDate,form.fromTime),to=couponUtcTime(form.toDate,form.toTime);if(!from||!to||Date.parse(from)>=Date.parse(to)||!form.invitee||form.scope==='OWNER'&&!form.inviter||form.source_note.trim().length<2){state.message='请填写来源、有效时间和奖励券。';return}const b={scope:form.scope,source_note:form.source_note.trim(),valid_from:from,valid_to:to,invitee_coupon_id:form.invitee.coupon_id,invitee_publication_revision:form.invitee.publication_revision,inviter_coupon_id:form.scope==='OWNER'?form.inviter.coupon_id:null,inviter_publication_revision:form.scope==='OWNER'?form.inviter.publication_revision:null,...(editing.value?{expected_revision:form.revision}:{})};flow.save(editing.value?'update':'create',editing.value,b)}
function status(r,s){flow.save('status',r.id,{expected_revision:r.revision,status:s})}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
</script>
<template><view class="reservation-page"><text class="reservation-title">邀请奖励规则配置</text><text>车主双方各一次；员工推广只奖励新客。规则发布不发券；后台按资格事件发放，具体到账见奖励记录。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有独立邀请规则权限。</text><template v-else>
 <view class="reservation-panel"><text>{{editing?'修改草稿':'新建草稿'}}</text><picker :range="['车主邀请','员工推广']" :disabled="state.busy||state.retry" @change="form.scope=Number($event.detail.value)===0?'OWNER':'STAFF'"><text>{{form.scope==='OWNER'?'车主双方奖励':'员工推广新客奖励'}}</text></picker><input v-model="form.source_note" :disabled="state.busy||state.retry" maxlength="256" placeholder="规则来源说明"/><text>北京时间生效日期/时间</text><input v-model="form.fromDate" :disabled="state.busy||state.retry" placeholder="YYYY-MM-DD"/><input v-model="form.fromTime" :disabled="state.busy||state.retry" placeholder="HH:mm"/><text>北京时间截止日期/时间</text><input v-model="form.toDate" :disabled="state.busy||state.retry" placeholder="YYYY-MM-DD"/><input v-model="form.toTime" :disabled="state.busy||state.retry" placeholder="HH:mm"/>
 <picker v-if="form.scope==='OWNER'" :range="state.offers.map(r=>r.terms.name+' · 门店'+r.merchant_id)" :disabled="state.busy||state.retry" @change="select('inviter',$event)"><text>邀请者奖励：{{form.inviter?.terms?.name|| (form.inviter?'已保存的券版本':'请选择')}}</text></picker><picker :range="state.offers.map(r=>r.terms.name+' · 门店'+r.merchant_id)" :disabled="state.busy||state.retry" @change="select('invitee',$event)"><text>新客奖励：{{form.invitee?.terms?.name||(form.invitee?'已保存的券版本':'请选择')}}</text></picker><text v-if="!state.offers.length">暂无可配置的精选已发布券。</text><button :disabled="state.busy||state.retry" @tap="save">保存草稿</button><button :disabled="state.busy||state.retry" @tap="clearForm">新建另一政策</button></view>
 <view v-for="r in state.rows" :key="r.id" class="reservation-panel"><text>{{r.scope==='OWNER'?'车主邀请':'员工推广'}} · {{r.status}} · 版本 {{r.revision}}</text><text>{{r.source_note}}</text><text>{{couponLocalTime(r.valid_from)}} 至 {{couponLocalTime(r.valid_to)}}</text><button v-if="r.status==='DRAFT'" :disabled="state.busy||state.retry" @tap="edit(r)">修改</button><button v-if="r.status==='DRAFT'" :disabled="state.busy||state.retry" @tap="status(r,'PUBLISHED')">发布冻结</button><button v-if="r.status==='PUBLISHED'" :disabled="state.busy||state.retry" @tap="status(r,'STOPPED')">停止使用</button></view>
 <text v-if="state.message">{{state.message}}</text><button v-if="state.kind==='unauthorized'" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原操作</button><button :disabled="state.busy" @tap="flow.load()">刷新</button><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1,state.offerPage)">规则上一页</button><button v-if="state.page*20<state.total" :disabled="state.busy" @tap="flow.load(state.page+1,state.offerPage)">规则下一页</button><button v-if="state.offerPage>1" :disabled="state.busy" @tap="flow.load(state.page,state.offerPage-1)">券池上一页</button><button v-if="state.offerPage*20<state.offerTotal" :disabled="state.busy" @tap="flow.load(state.page,state.offerPage+1)">券池下一页</button></template></view></template>
